theorem String.crlfToLf.go.eq_def✝ (text acc : String) (accStop pos : String.Pos.Raw) :
  String.crlfToLf.go✝ text acc accStop pos =
    if h : String.Pos.Raw.atEnd text pos = true then
      if accStop = 0 then text else acc ++ String.Pos.Raw.extract text accStop pos
    else
      let c := String.Pos.Raw.get' text pos h;
      let pos' := String.Pos.Raw.next' text pos h;
      if h' :
          ¬String.Pos.Raw.atEnd text pos' = true ∧
            (c == '\x0d') = true ∧ (String.Pos.Raw.get text pos' == '\n') = true then
        have acc := acc ++ String.Pos.Raw.extract text accStop pos;
        String.crlfToLf.go✝ text acc pos' (String.Pos.Raw.next' text pos' ⋯)
      else String.crlfToLf.go✝ text acc accStop pos'

