theorem Vector.toArray_mapM.{u_1, u_2, u_3} {m : Type u_1 → Type u_2} {α : Type u_3} {β : Type u_1} {n : ℕ}
  [Monad m] [LawfulMonad m] {f : α → m β} {xs : Vector α n} :
  Vector.toArray <$> Vector.mapM f xs = Array.mapM f xs.toArray

theorem Vector.flatMap_mk.{u_1, u_2} {α : Type u_1} {β : Type u_2} {m n : ℕ} {f : α → Vector β m}
  {xs : Array α} (h : xs.size = n) :
  (Vector.mk xs h).flatMap f = Vector.mk (Array.flatMap (fun a => (f a).toArray) xs) ⋯

theorem Vector.foldlM_pure.{u_1, u_2, u_3} {m : Type u_1 → Type u_2} {β : Type u_1} {α : Type u_3} {n : ℕ}
  [Monad m] [LawfulMonad m] {f : β → α → β} {b : β} {xs : Vector α n} :
  Vector.foldlM (fun x1 x2 => pure (f x1 x2)) b xs = pure (Vector.foldl f b xs)

theorem Vector.findSomeRevM?_toArray.{u_1, u_2, u_3} {m : Type u_1 → Type u_2} {α : Type u_3} {β : Type u_1}
  {n : ℕ} [Monad m] {f : α → m (Option β)} {xs : Vector α n} :
  Array.findSomeRevM? f xs.toArray = Vector.findSomeRevM? f xs

theorem Vector.map_eq_append_iff.{u_1, u_2} {α : Type u_1} {β : Type u_2} {a✝ a✝¹ : ℕ}
  {xs : Vector α (a✝ + a✝¹)} {ys : Vector β a✝} {zs : Vector β a✝¹} {f : α → β} :
  Vector.map f xs = ys ++ zs ↔ ∃ as bs, xs = as ++ bs ∧ Vector.map f as = ys ∧ Vector.map f bs = zs

theorem Vector.firstM_mk.{u_1, u_2, u_3} {m : Type u_1 → Type u_2} {α : Type u_3} {β : Type u_1} {n : ℕ}
  [Alternative m] {f : α → m β} {xs : Array α} (h : xs.size = n) :
  Vector.firstM f (Vector.mk xs h) = Array.firstM f xs

theorem Vector.foldr_flatMap.{u_1, u_2, u_3} {α : Type u_1} {β : Type u_2} {m : ℕ} {γ : Type u_3} {n : ℕ}
  {f : α → Vector β m} {g : β → γ → γ} {xs : Vector α n} {init : γ} :
  Vector.foldr g init (xs.flatMap f) = Vector.foldr (fun x acc => Vector.foldr g acc (f x)) init xs

theorem Vector.foldrM_mk.{u_1, u_2, u_3} {m : Type u_1 → Type u_2} {α : Type u_3} {β : Type u_1} {n : ℕ}
  [Monad m] {f : α → β → m β} {b : β} {xs : Array α} (h : xs.size = n) :
  Vector.foldrM f b (Vector.mk xs h) = Array.foldrM f b xs

theorem Vector.findSomeRevM?_mk.{u_1, u_2, u_3} {m : Type u_1 → Type u_2} {α : Type u_3} {n : ℕ}
  {β : Type u_1} [Monad m] {xs : Array α} (h : xs.size = n) (f : α → m (Option β)) :
  Vector.findSomeRevM? f (Vector.mk xs h) = Array.findSomeRevM? f xs

theorem Vector.getElem_replace.{u_1} {α : Type u_1} [BEq α] [LawfulBEq α] {n : ℕ} {a b : α}
  {xs : Vector α n} {i : ℕ} (h : i < n) :
  (xs.replace a b)[i] = if (xs[i] == a) = true then if a ∈ xs.take i then a else b else xs[i]

theorem Vector.foldr_append.{u_1, u_2} {α : Type u_1} {β : Type u_2} {n k : ℕ} {f : α → β → β} {b : β}
  {xs : Vector α n} {ys : Vector α k} :
  Vector.foldr f b (xs ++ ys) = Vector.foldr f (Vector.foldr f b ys) xs

theorem Vector.append_flatten.{u_1} {α : Type u_1} {n m₁ m₂ : ℕ} {xss₁ : Vector (Vector α n) m₁}
  {xss₂ : Vector (Vector α n) m₂} :
  xss₁.flatten ++ xss₂.flatten = Vector.cast ⋯ (xss₁ ++ xss₂).flatten
